  set_test_initialization_stage("register-renderer-settings");
 auto& config=debug_overlay_.config();config.register_boolean("confine_cursor","Confine cursor to game client area","Input",true,false,"Keeps pointer-driven camera and interaction input inside the active game client area; releases immediately when the game loses focus.");config.register_boolean("vsync","Vertical sync","Presentation",present_interval()!=0,false,"Use a synchronized Present interval. Disabled remains the uncapped performance default. Forced off in developer mode.");config.register_integer("background_mode","In the background","Presentation",0,0,1,1,false,"What the game does while its window is not in front. 0: keeps running and drawing (capped by the background frame limit). 1: pauses; the world stops and the last frame stays on screen. Either way it never minimises itself or reloads its textures on return.");config.register_integer("background_frame_limit","Background frame limit (FPS)","Presentation",30,0,240,1,false,"While the game window is not in front, Present is paced to at most this many frames per second, so a game left in the background idles quietly. 0: off.");config.register_integer("frame_limit","Frame rate limit (FPS)","Presentation",0,0,500,1,false,"0: off (uncapped). Otherwise Present is paced to this many frames per second, measured from the previous present (high-resolution timer plus a short final spin). Forced off in developer mode.");config.register_boolean("shadows","Shadows","Graphics",true,false,"Render owned directional shadow maps and sample them in world shading. Changes apply at the next scene boundary.");config.register_boolean("terrain_normal_sunlight","Terrain normal sunlight","Graphics",true,false,"Compare terrain shading. On uses terrain normals for direct sun; off applies full direct sun while keeping projected shadows, ambient light, textures, and fog.");
