 const HRESULT hr=draw(D3DPT_TRIANGLELIST,D3DFVF_XYZRHW|D3DFVF_DIFFUSE|D3DFVF_SPECULAR|D3DFVF_TEX1,
             vertices.data(),UINT(vertices.size()),nullptr,0,state,nullptr,SemanticKind::ui,0,0,{},texture.Get());
