  D3D11_BUFFER_DESC description{};description.ByteWidth=count*sizeof(NativePoseNodeGpu);
  description.Usage=D3D11_USAGE_DEFAULT;description.BindFlags=D3D11_BIND_SHADER_RESOURCE|D3D11_BIND_UNORDERED_ACCESS;
